const prepare = function prepareUrls({ urlsJson }) {
  let raw;
  try { raw = JSON.parse(urlsJson); } catch { throw new Error('Page URLs must be a JSON array.'); }
  if (!Array.isArray(raw)) throw new Error('Page URLs must be a JSON array.');
  const urls = raw.slice(0, 40).map(url => {
    if (typeof url !== 'string' || !/^https?:\/\/[^\s/]+(?:\/[^\s]*)?$/i.test(url.trim())) throw new Error('Each selected page needs a nonempty HTTP or HTTPS URL.');
    return url.trim();
  });
  return { urls, inputCount: raw.length, skippedCount: Math.max(raw.length - 40, 0) };
}

const result=prepare($input.first().json);return result.urls.map((url,index)=>({json:{url,inputCount:result.inputCount,skippedCount:result.skippedCount},pairedItem:{item:0}}));

const readPage = function readPage({ url, result }) {
  if (!result || result.success !== true || !result.data || typeof result.data !== 'object' || Array.isArray(result.data)) throw new Error('Firecrawl did not return a successful page scrape.');
  const data = result.data;
  if (typeof data.markdown !== 'string' || !Array.isArray(data.links) || data.links.some(link => typeof link !== 'string')) throw new Error('Firecrawl omitted the requested Markdown or link array.');
  const text = value => value == null ? '' : typeof value === 'string' ? value : (() => { throw new Error('Page metadata must be text when present.'); })();
  const status = data.metadata?.statusCode;
  return { page: { url, title: text(data.metadata?.title), description: text(data.metadata?.description), content: data.markdown, links: data.links, pageStatus: Number.isInteger(status) && status >= 100 && status <= 599 ? status : null } };
}

const urls=$('One URL at a time').all(1).map(item=>item.json.url),items=$input.all();if(items.length!==urls.length)throw new Error('Page response count differs from this URL group.');return items.map((item,index)=>({json:readPage({url:urls[index],result:item.json}).page,pairedItem:{item:index}}));
